import tensorflow as tf

def reduce_parameters(model):
  # Replace dense layers with only one neuron (linear bottleneck)
  # by replacing the number of neurons in the dense layers by one
  for layer in model.layers:
    if isinstance(layer, tf.keras.layers.Dense):
      layer.units = 1

  return model
