import pandas as pd

# Read data from csv
data = pd.read_csv('assembly_parameters.csv') 

# Set all parameters which are constrained
constrained_params = ['P1', 'P2', 'P3'] 

# Determine current optimization score
initial_score = 0 
for param in data.columns:
  initial_score += data[param].mean() 

# Define multi-stage optimization procedure
def optimize():
  cur_score = initial_score 
  for i in range(500):
    # Generate new (random) candidate parameters
    new_candidates = generate_candidates() 
    # Evaluate candidate parameters using current production metrics
    candidate_score = evaluate_candidates(new_candidates) 
    # Accept new parameters if score improves
    if candidate_score > cur_score:
      for param in data.columns:
        if param not in constrained_params:
          data[param] = new_candidates[param] 
      cur_score = candidate_score 
    else:
      continue 
  return data 

# Generate new (random) candidates
def generate_candidates():
  params = {}
  for param in data.columns:
    if param not in constrained_params:
      params[param] = np.random.randint(low = 0, high = 100) 
  return params 

# Evaluate candidate parameters using current production metrics
def evaluate_candidates(candidates):
  score = 0
  for param in candidates:
    score += candidates[param] 
  return score 

# Optimize processes
data = optimize()
```

